const ONE_MINUTE_MS = 60 * 1000;
const CACHING_TIME = ONE_MINUTE_MS;

/** Expand the start date to the start of the month */
function getTimeMin(timeMin: string) {
  const dateMin = new Date(timeMin);
  return new Date(dateMin.getFullYear(), dateMin.getMonth(), 1, 0, 0, 0, 0).toISOString();
}

/** Expand the end date to the end of the month */
function getTimeMax(timeMax: string) {
  const dateMax = new Date(timeMax);
  return new Date(dateMax.getFullYear(), dateMax.getMonth() + 1, 0, 0, 0, 0, 0).toISOString();
}

/**
 * Enable or disable the expanded cache
 * TODO: Make this configurable
 * */
const ENABLE_EXPANDED_CACHE = true;

/**
 * By expanding the cache to whole months, we can save round trips to the third party APIs.
 * In this case we already have the data in the database, so we can just return it.
 */
function handleMinMax(min: string, max: string) {
  if (!ENABLE_EXPANDED_CACHE) return { timeMin: min, timeMax: max };
  return { timeMin: getTimeMin(min), timeMax: getTimeMax(max) };
}

export default class GoogleCalendarService implements Calendar {
  private integrationName = "";
  private auth: { getToken: () => Promise<MyGoogleAuth> };
  private log: typeof logger;
  private credential: CredentialPayload;

  constructor(credential: CredentialPayload) {
    this.integrationName = "google_calendar";
    this.credential = credential;
    this.auth = this.googleAuth(credential);
    this.log = logger.getChildLogger({ prefix: [`[[lib] ${this.integrationName}`] });
    this.credential = credential;
  }

  private googleAuth = (credential: CredentialPayload) => {
    const googleCredentials = googleCredentialSchema.parse(credential.key);

    async function getGoogleAuth() {
      const { client_id, client_secret, redirect_uris } = await getGoogleAppKeys();
      const myGoogleAuth = new MyGoogleAuth(client_id, client_secret, redirect_uris[0]);
      myGoogleAuth.setCredentials(googleCredentials);
      return myGoogleAuth;
    }

    const refreshAccessToken = async (myGoogleAuth: Awaited<ReturnType<typeof getGoogleAuth>>) => {
      try {
        const res = await refreshOAuthTokens(
          async () => {
            const fetchTokens = await myGoogleAuth.refreshToken(googleCredentials.refresh_token);
            return fetchTokens.res;
          },
          "google-calendar",
          credential.userId
        );
        const token = res?.data;
        googleCredentials.access_token = token.access_token;
        googleCredentials.expiry_date = token.expiry_date;
        const key = parseRefreshTokenResponse(googleCredentials, googleCredentialSchema);
        await prisma.credential.update({
          where: { id: credential.id },
          data: { key },
        });
        myGoogleAuth.setCredentials(googleCredentials);
      } catch (err) {
        let message;
        if (err instanceof Error) message = err.message;
        else message = String(err);
        // if not invalid_grant, default behaviour (which admittedly isn't great)
        if (message !== "invalid_grant") return myGoogleAuth;
        // when the error is invalid grant, it's unrecoverable and the credential marked invalid.
        // TODO: Evaluate bubbling up and handling this in the CalendarManager. IMO this should be done
        //       but this is a bigger refactor.
        await prisma.credential.update({
          where: { id: credential.id },
          data: {
            invalid: true,
          },
        });
      }
      return myGoogleAuth;
    };
    return {
      getToken: async () => {
        const myGoogleAuth = await getGoogleAuth();
        const isExpired = () => myGoogleAuth.isTokenExpiring();
        return !isExpired() ? Promise.resolve(myGoogleAuth) : refreshAccessToken(myGoogleAuth);
      },
    };
  };

  private authedCalendar = async () => {
    const myGoogleAuth = await this.auth.getToken();
    const calendar = google.calendar({
      version: "v3",
      auth: myGoogleAuth,
    });
    return calendar;
  };

  private getAttendees = (event: CalendarEvent) => {
    // When rescheduling events we know the external id of the calendar so we can just look for it in the destinationCalendar array.
    const selectedHostDestinationCalendar = event.destinationCalendar?.find(
      (cal) => cal.credentialId === this.credential.id
    );
    const eventAttendees = event.attendees.map(({ id: _id, ...rest }) => ({
      ...rest,
      responseStatus: "accepted",
    }));
    const attendees: calendar_v3.Schema$EventAttendee[] = [
      {
        ...event.organizer,
        id: String(event.organizer.id),
        responseStatus: "accepted",
        organizer: true,
        // Tried changing the display name to the user but GCal will not let you do that. It will only display the name of the external calendar. Leaving this in just incase it works in the future.
        displayName: event.organizer.name,
        email: selectedHostDestinationCalendar?.externalId ?? event.organizer.email,
      },
      ...eventAttendees,
    ];

    if (event.team?.members) {
      // TODO: Check every other CalendarService for team members
      const teamAttendeesWithoutCurrentUser = event.team.members
        .filter((member) => member.email !== this.credential.user?.email)
        .map((m) => {
          const teamMemberDestinationCalendar = event.destinationCalendar?.find(
            (calendar) => calendar.integration === "google_calendar" && calendar.userId === m.id
          );
          return {
            email: teamMemberDestinationCalendar?.externalId ?? m.email,
            displayName: m.name,
            responseStatus: "accepted",
          };
        });
      attendees.push(...teamAttendeesWithoutCurrentUser);
    }

  } catch (err) {
    console.log(err);
    return Promise.reject([]);
  }
}

async listCalendars(): Promise<IntegrationCalendar[]> {
  const officeCalendars: OfficeCalendar[] = [];
  // List calendars from MS are paginated
  let finishedParsingCalendars = false;
  const calendarFilterParam = "$select=id,name,isDefaultCalendar,canEdit";

  // Store @odata.nextLink if in response
  let requestLink = `/me/calendars?${calendarFilterParam}`;

  while (!finishedParsingCalendars) {
    const response = await this.fetcher(requestLink);
    let responseBody = await handleErrorsJson<{ value: OfficeCalendar[]; "@odata.nextLink"?: string }>(
      response
    );
    // If responseBody is valid then parse the JSON text
    if (typeof responseBody === "string") {
      responseBody = JSON.parse(responseBody) as { value: OfficeCalendar[] };
    }

    officeCalendars.push(...responseBody.value);

    if (responseBody["@odata.nextLink"]) {
      requestLink = responseBody["@odata.nextLink"].replace(this.apiGraphUrl, "");
    } else {
      finishedParsingCalendars = true;
    }
  }

  const user = await this.fetcher("/me");
  const userResponseBody = await handleErrorsJson<User>(user);
  const email = userResponseBody.mail ?? userResponseBody.userPrincipalName;

  return officeCalendars.map((cal: OfficeCalendar) => {
    const calendar: IntegrationCalendar = {
      externalId: cal.id ?? "No Id",
      integration: this.integrationName,
      name: cal.name ?? "No calendar name",
      primary: cal.isDefaultCalendar ?? false,
      readOnly: !cal.canEdit && true,
      email: email ?? "",
    };
    return calendar;
  });
}

private o365Auth = (credential: CredentialPayload) => {
  const isExpired = (expiryDate: number) => {
    if (!expiryDate) {
      return true;
    } else {
      return expiryDate < Math.round(+new Date() / 1000);
    }
  };
  const o365AuthCredentials = credential.key as O365AuthCredentials;

  const refreshAccessToken = async (o365AuthCredentials: O365AuthCredentials) => {
    const { client_id, client_secret } = await getOfficeAppKeys();
    const response = await refreshOAuthTokens(
      async () =>
        await fetch("https://login.microsoftonline.com/common/oauth2/v2.0/token", {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            scope: "User.Read Calendars.Read Calendars.ReadWrite",
            client_id,
            refresh_token: o365AuthCredentials.refresh_token,
            grant_type: "refresh_token",
            client_secret,
          }),
        }),
      "office365-calendar",
      credential.userId
    );
    const responseJson = await handleErrorsJson(response);
    const tokenResponse = parseRefreshTokenResponse(responseJson, refreshTokenResponseSchema);
    o365AuthCredentials = { ...o365AuthCredentials, ...(tokenResponse.success && tokenResponse.data) };
    await prisma.credential.update({
      where: {
        id: credential.id,
      },
      data: {
        key: o365AuthCredentials,
      },
    });
    return o365AuthCredentials.access_token;
  };

  return {
    getToken: () =>
      refreshTokenResponseSchema.safeParse(o365AuthCredentials).success &&
      !isExpired(o365AuthCredentials.expires_in)
        ? Promise.resolve(o365AuthCredentials.access_token)
        : refreshAccessToken(o365AuthCredentials),
  };
};

private translateEvent = (event: CalendarEvent) => {
  return {
    subject: event.title,
    body: {
      contentType: "HTML",
      content: getRichDescription(event),
    },
    start: {
      dateTime: dayjs(event.startTime).tz(event.organizer.timeZone).format("YYYY-MM-DDTHH:mm:ss"),
      timeZone: event.organizer.timeZone,
    },
    end: {
      dateTime: dayjs(event.endTime).tz(event.organizer.timeZone).format("YYYY-MM-DDTHH:mm:ss"),
      timeZone: event.organizer.timeZone,
    },
    attendees: [
      // Add the calEvent organizer
      {
        emailAddress: {
          address: event.destinationCalendar
            ? event.destinationCalendar.find((cal) => cal.userId === event.organizer.id)?.externalId ??
              event.organizer.email
            : event.organizer.email,
          name: event.organizer.name,
        },
      },
      ...event.attendees.map((attendee) => ({
        emailAddress: {
          address: attendee.email,
          name: attendee.name,
        },
        type: "required",
      })),
      ...(event.team?.members
        ? event.team?.members
            .filter((member) => member.email !== this.credential.user?.email)
            .map((member) => {
              const destinationCalendar =
                event.destinationCalendar &&
                event.destinationCalendar.find((cal) => cal.userId === member.id);
              return {
                emailAddress: {
                  address: destinationCalendar?.externalId ?? member.email,
                  name: member.name,
                },
                type: "required",
              };
            })
        : []),
    ],
    location: event.location ? { displayName: getLocation(event) } : undefined,
  };
};

